"""Tests for validated terminology configuration and domain resolution."""

from __future__ import annotations

import json
import tempfile
import unittest
from pathlib import Path

from agent_workshop_demo.entities import (
    entity_catalog_from_mapping,
    load_entity_catalog,
)


class EntityCatalogTests(unittest.TestCase):
    def test_go_button_aliases_resolve_to_one_reviewed_entity(self) -> None:
        catalog = load_entity_catalog()

        for surface in ["GO按钮", "跳转按钮", "领取按钮"]:
            with self.subTest(surface=surface):
                result = catalog.resolve(
                    f"产品中的{surface}是什么意思？",
                    query_type="product",
                )
                self.assertEqual(len(result.matched), 1)
                self.assertEqual(
                    result.matched[0]["entity_id"],
                    "ui.go_button",
                )
                self.assertEqual(result.ambiguous, ())

    def test_same_surface_requires_domain_context(self) -> None:
        catalog = load_entity_catalog()

        ambiguous = catalog.resolve("段位是什么意思？", query_type="unknown")
        game = catalog.resolve(
            "游戏中的段位是什么意思？",
            query_type="unknown",
        )

        self.assertEqual(ambiguous.matched, ())
        self.assertEqual(ambiguous.ambiguous[0]["status"], "ambiguous")
        self.assertEqual(game.matched[0]["entity_id"], "game.rank_tier")

    def test_loader_rejects_duplicate_ids_and_unknown_fields(self) -> None:
        duplicate = {
            "catalog_version": "1",
            "entities": [
                {
                    "entity_id": "same",
                    "entity": "A",
                    "aliases": [],
                    "comment": "first",
                    "domains": ["product"],
                },
                {
                    "entity_id": "same",
                    "entity": "B",
                    "aliases": [],
                    "comment": "second",
                    "domains": ["game"],
                },
            ],
        }
        with self.assertRaisesRegex(ValueError, "unique"):
            entity_catalog_from_mapping(duplicate)

        with tempfile.TemporaryDirectory() as temp_dir:
            path = Path(temp_dir) / "entities.yaml"
            path.write_text(
                json.dumps(
                    {
                        "catalog_version": "1",
                        "entities": [],
                        "unexpected": True,
                    }
                ),
                encoding="utf-8",
            )
            with self.assertRaisesRegex(ValueError, "unknown fields"):
                load_entity_catalog(path)

    def test_prompt_cap_does_not_hide_later_ambiguity(self) -> None:
        entities = [
            {
                "entity_id": f"general.term_{index}",
                "entity": f"术语{index}",
                "aliases": [],
                "comment": f"定义 {index}",
                "domains": ["product"],
            }
            for index in range(20)
        ]
        entities.extend(
            [
                {
                    "entity_id": "game.rank",
                    "entity": "段位",
                    "aliases": [],
                    "comment": "游戏竞技等级",
                    "domains": ["game"],
                },
                {
                    "entity_id": "hr.rank",
                    "entity": "段位",
                    "aliases": [],
                    "comment": "人才职级",
                    "domains": ["hr"],
                },
            ]
        )
        catalog = entity_catalog_from_mapping(
            {"catalog_version": "cap-test", "entities": entities}
        )
        question = " ".join(
            [*(f"术语{index}" for index in range(20)), "段位"]
        )

        resolution = catalog.resolve(question, query_type="unknown")

        self.assertEqual(len(resolution.matched), 20)
        self.assertEqual(len(resolution.ambiguous), 1)
        self.assertEqual(resolution.ambiguous[0]["status"], "ambiguous")


if __name__ == "__main__":
    unittest.main()

from __future__ import annotations

import math
import unittest
from types import SimpleNamespace
from typing import Any

from agent_workshop_demo.embedding import (
    DeterministicTextEmbeddingProvider,
    OpenAITextEmbeddingProvider,
    TextEmbeddingProvider,
    TextEmbeddingError,
    build_text_embedding_provider,
    embedding_metadata,
)


class RecordingEmbeddings:
    def __init__(self, vector: list[float]) -> None:
        self.vector = vector
        self.calls: list[dict[str, Any]] = []

    def create(self, **kwargs: Any) -> SimpleNamespace:
        self.calls.append(kwargs)
        return SimpleNamespace(
            data=[SimpleNamespace(embedding=self.vector)]
        )


class RecordingOpenAIClient:
    def __init__(self, vector: list[float]) -> None:
        self.embeddings = RecordingEmbeddings(vector)


class FailingEmbeddings:
    def create(self, **kwargs: Any) -> SimpleNamespace:
        raise TimeoutError("secret provider response")


class FailingOpenAIClient:
    def __init__(self) -> None:
        self.embeddings = FailingEmbeddings()


class EmbeddingTests(unittest.TestCase):
    def test_openai_provider_sends_dimension_preserving_request(self) -> None:
        client = RecordingOpenAIClient([0.1, 0.2, 0.3])
        provider = OpenAITextEmbeddingProvider(
            client=client,
            model="text-embedding-3-small",
            timeout_seconds=8.5,
        )

        vector = provider.embed("Milvus 文档", dimensions=3)

        self.assertEqual(vector, [0.1, 0.2, 0.3])
        self.assertEqual(
            client.embeddings.calls,
            [
                {
                    "input": "Milvus 文档",
                    "model": "text-embedding-3-small",
                    "dimensions": 3,
                    "encoding_format": "float",
                    "timeout": 8.5,
                }
            ],
        )

    def test_openai_provider_rejects_invalid_vectors(self) -> None:
        invalid_vectors = [
            [0.1],
            [0.1, math.nan],
            [0.1, math.inf],
        ]

        for vector in invalid_vectors:
            with self.subTest(vector=vector):
                provider = OpenAITextEmbeddingProvider(
                    client=RecordingOpenAIClient(vector),
                    model="text-embedding-3-small",
                )
                with self.assertRaisesRegex(
                    TextEmbeddingError,
                    "invalid_provider_output",
                ):
                    provider.embed("valid text", dimensions=2)

    def test_openai_provider_sanitizes_provider_failure(self) -> None:
        provider = OpenAITextEmbeddingProvider(
            client=FailingOpenAIClient(),
            model="text-embedding-3-small",
        )

        with self.assertRaises(TextEmbeddingError) as raised:
            provider.embed("sensitive document", dimensions=2)

        self.assertEqual(raised.exception.reason_code, "timeout")
        self.assertIsNone(raised.exception.__cause__)
        self.assertIsNone(raised.exception.__context__)
        self.assertNotIn("secret provider response", str(raised.exception))
        self.assertNotIn("sensitive document", str(raised.exception))

    def test_providers_reject_empty_text_before_network_io(self) -> None:
        client = RecordingOpenAIClient([0.1, 0.2])
        providers: list[TextEmbeddingProvider] = [
            DeterministicTextEmbeddingProvider(),
            OpenAITextEmbeddingProvider(
                client=client,
                model="text-embedding-3-small",
            ),
        ]

        for provider in providers:
            with self.subTest(provider=provider.name):
                with self.assertRaisesRegex(ValueError, "non-empty"):
                    provider.embed("  ", dimensions=2)

        self.assertEqual(client.embeddings.calls, [])

    def test_auto_mode_without_key_uses_deterministic_provider(self) -> None:
        provider = build_text_embedding_provider(
            {"EMBEDDING_PROVIDER": "auto"}
        )

        self.assertIsInstance(provider, DeterministicTextEmbeddingProvider)

    def test_default_mode_never_uses_ambient_openai_key(self) -> None:
        client_factory_called = False

        def client_factory(api_key: str) -> RecordingOpenAIClient:
            nonlocal client_factory_called
            client_factory_called = True
            return RecordingOpenAIClient([0.1, 0.2])

        provider = build_text_embedding_provider(
            {"OPENAI_API_KEY": "ambient-key"},
            client_factory=client_factory,
        )

        self.assertIsInstance(provider, DeterministicTextEmbeddingProvider)
        self.assertFalse(client_factory_called)

    def test_auto_mode_with_key_uses_default_openai_model(self) -> None:
        client = RecordingOpenAIClient([0.1, 0.2])

        provider = build_text_embedding_provider(
            {
                "EMBEDDING_PROVIDER": "auto",
                "OPENAI_API_KEY": "test-key",
            },
            client_factory=lambda api_key: client,
        )

        provider.embed("query", dimensions=2)

        self.assertIsInstance(provider, OpenAITextEmbeddingProvider)
        self.assertEqual(
            client.embeddings.calls[0]["model"],
            "text-embedding-3-small",
        )

    def test_openai_mode_uses_explicit_configuration(self) -> None:
        client = RecordingOpenAIClient([0.1, 0.2])
        received_keys: list[str] = []

        def client_factory(api_key: str) -> RecordingOpenAIClient:
            received_keys.append(api_key)
            return client

        provider = build_text_embedding_provider(
            {
                "EMBEDDING_PROVIDER": "openai",
                "OPENAI_API_KEY": "test-key",
                "OPENAI_EMBEDDING_MODEL": "configured-model",
                "OPENAI_EMBEDDING_TIMEOUT_SECONDS": "7.5",
            },
            client_factory=client_factory,
        )

        vector = provider.embed("query", dimensions=2)

        self.assertEqual(received_keys, ["test-key"])
        self.assertEqual(vector, [0.1, 0.2])
        self.assertEqual(client.embeddings.calls[0]["model"], "configured-model")
        self.assertEqual(client.embeddings.calls[0]["timeout"], 7.5)

    def test_invalid_embedding_configuration_fails_clearly(self) -> None:
        invalid_environments = [
            {"EMBEDDING_PROVIDER": "unknown"},
            {"EMBEDDING_PROVIDER": "openai"},
            {
                "EMBEDDING_PROVIDER": "openai",
                "OPENAI_API_KEY": "key",
                "OPENAI_EMBEDDING_TIMEOUT_SECONDS": "0",
            },
            {
                "EMBEDDING_PROVIDER": "openai",
                "OPENAI_API_KEY": "key",
                "OPENAI_EMBEDDING_TIMEOUT_SECONDS": "nan",
            },
            {
                "EMBEDDING_PROVIDER": "openai",
                "OPENAI_API_KEY": "key",
                "OPENAI_EMBEDDING_TIMEOUT_SECONDS": "inf",
            },
        ]

        for environ in invalid_environments:
            with self.subTest(environ=environ):
                with self.assertRaises(ValueError):
                    build_text_embedding_provider(environ)

    def test_embedding_metadata_records_provider_model_and_dimension(
        self,
    ) -> None:
        metadata = embedding_metadata({"parser": "markdown"}, dimensions=3)

        self.assertEqual(metadata["parser"], "markdown")
        self.assertEqual(
            metadata["text_embedding_fingerprint"],
            "deterministic:sha256-token-v1:3",
        )


if __name__ == "__main__":
    unittest.main()

from __future__ import annotations

import json
import unittest
from types import SimpleNamespace
from typing import Any

from agent_workshop_demo.query_transform import (
    OpenAIQueryTransformer,
    QueryTransformRequest,
    RuleBasedQueryTransformer,
    build_query_transformer,
)


class RecordingResponses:
    def __init__(self, output: object) -> None:
        self.output = output
        self.calls: list[dict[str, Any]] = []

    def create(self, **kwargs: Any) -> SimpleNamespace:
        self.calls.append(kwargs)
        return SimpleNamespace(output_text=json.dumps(self.output, ensure_ascii=False))


class QueryTransformTests(unittest.TestCase):
    def test_rule_policy_selects_one_bounded_strategy(self) -> None:
        transformer = RuleBasedQueryTransformer()
        cases = [
            ("Force Merge 是什么？", "identity", ["primary"]),
            ("它怎么弄？", "rewrite", ["primary"]),
            ("Milvus Force Merge 为什么这样工作？", "step_back", ["background", "primary"]),
            ("比较 Milvus v2.6 和 v3.0", "decompose", ["aspect", "aspect"]),
        ]
        for query, strategy, roles in cases:
            with self.subTest(query=query):
                result = transformer.transform(
                    QueryTransformRequest(
                        query,
                        resolved_entities=("Milvus",) if "它" in query else (),
                    )
                )
                self.assertEqual(result.strategy, strategy)
                self.assertEqual([item.query_role for item in result.items], roles)
                self.assertLessEqual(len(result.items), 3)

    def test_step_back_and_decompose_preserve_versions_and_named_terms(self) -> None:
        transformer = RuleBasedQueryTransformer()
        for query in (
            "Milvus v3.0 Force Merge 为什么不能在线执行？",
            "比较 Milvus v2.6 和 v3.0 的 Force Merge",
        ):
            result = transformer.transform(QueryTransformRequest(query))
            for item in result.items:
                self.assertIn("Milvus", item.query)
                self.assertIn("Force Merge", item.query)
                if "v3.0" in query:
                    self.assertIn("v3.0", item.query)
                if "v2.6" in query:
                    self.assertIn("v2.6", item.query)

    def test_openai_transformer_uses_one_strict_request(self) -> None:
        responses = RecordingResponses(
            {
                "strategy": "step_back",
                "items": [
                    {
                        "query": "Milvus v3.0 Force Merge 如何工作？；背景架构",
                        "query_role": "background",
                        "depends_on": [],
                    },
                    {
                        "query": "Milvus v3.0 Force Merge 如何工作？",
                        "query_role": "primary",
                        "depends_on": [],
                    },
                ],
            }
        )
        transformer = OpenAIQueryTransformer(
            client=SimpleNamespace(responses=responses),
            model="test-model",
        )

        result = transformer.transform(
            QueryTransformRequest("Milvus v3.0 Force Merge 如何工作？")
        )

        self.assertEqual(result.strategy, "step_back")
        self.assertEqual(len(responses.calls), 1)
        self.assertEqual(
            responses.calls[0]["text"]["format"]["schema"]["additionalProperties"],
            False,
        )

    def test_invalid_provider_output_falls_back_without_losing_terms(self) -> None:
        responses = RecordingResponses(
            {
                "strategy": "rewrite",
                "items": [
                    {
                        "query": "合并怎么工作？",
                        "query_role": "primary",
                        "depends_on": [],
                    }
                ],
            }
        )
        transformer = build_query_transformer(
            {
                "QUERY_TRANSFORMER": "openai",
                "OPENAI_API_KEY": "test-key",
                "OPENAI_MODEL": "test-model",
            },
            client_factory=lambda _key: SimpleNamespace(responses=responses),
        )

        result = transformer.transform(
            QueryTransformRequest("Milvus v3.0 Force Merge 如何工作？")
        )

        self.assertEqual(result.fallback_reason, "invalid_model_output")
        self.assertTrue(all("Milvus" in item.query for item in result.items))
        self.assertEqual(len(responses.calls), 1)

    def test_provider_cannot_drop_unregistered_product_or_feature_terms(self) -> None:
        responses = RecordingResponses(
            {
                "strategy": "rewrite",
                "items": [
                    {
                        "query": "v3.0 如何工作？",
                        "query_role": "primary",
                        "depends_on": [],
                    }
                ],
            }
        )
        transformer = build_query_transformer(
            {
                "QUERY_TRANSFORMER": "openai",
                "OPENAI_API_KEY": "test-key",
                "OPENAI_MODEL": "test-model",
            },
            client_factory=lambda _key: SimpleNamespace(responses=responses),
        )

        result = transformer.transform(
            QueryTransformRequest("Milvus v3.0 Force Merge 如何工作？")
        )

        self.assertEqual(result.fallback_reason, "invalid_model_output")
        self.assertTrue(
            all(
                "Milvus v3.0 Force Merge 如何工作？" in item.query
                for item in result.items
            )
        )

    def test_default_builder_is_offline_and_explicit_mode_is_strict(self) -> None:
        self.assertEqual(build_query_transformer({}).name, "rule_based")
        with self.assertRaises(ValueError):
            build_query_transformer({"QUERY_TRANSFORMER": "openai"})


if __name__ == "__main__":
    unittest.main()
